-- Reviewed 13 October 2026. Original paraphrases, not official endorsements.
-- O*NET occupational data: National Center for O*NET Development, CC BY 4.0.
-- https://www.onetonline.org/help/license . U.S. occupations are NOT Malaysian admission rules.
-- Only exact original 0009/0013 seeds are updated. Admin content remains pending, untouched.
create table if not exists public.career_content_migration_backups (
 migration_key text not null, career_id uuid not null, career_record jsonb not null,
 stage_records jsonb not null, captured_at timestamptz not null default now(), primary key(migration_key,career_id)
);
create table if not exists public.career_content_migration_outcomes (
 migration_key text not null, career_id uuid not null, status text not null check(status in ('updated','skipped','missing')),
 reason text not null, reviewed_hash text, recorded_at timestamptz not null default now(), primary key(migration_key,career_id)
);
alter table public.career_content_migration_backups enable row level security;
alter table public.career_content_migration_outcomes enable row level security;
revoke all on public.career_content_migration_backups,public.career_content_migration_outcomes from anon,authenticated;
grant select on public.career_content_migration_backups,public.career_content_migration_outcomes to authenticated;
grant all on public.career_content_migration_backups,public.career_content_migration_outcomes to service_role;
drop policy if exists career_backup_admin_read on public.career_content_migration_backups;
create policy career_backup_admin_read on public.career_content_migration_backups for select to authenticated using(public.is_admin());
drop policy if exists career_outcome_admin_read on public.career_content_migration_outcomes;
create policy career_outcome_admin_read on public.career_content_migration_outcomes for select to authenticated using(public.is_admin());

create or replace function public.career_reviewed_snapshot(c public.careers) returns jsonb
language sql stable set search_path=public as $$
 select jsonb_build_object('career',to_jsonb(c),'stages',coalesce((select jsonb_agg(to_jsonb(s)-'id' order by s.from_education_level,s.stage_order) from public.career_pathway_stages s where s.career_id=c.id),'[]'::jsonb));
$$;

-- Temporary construction helpers; only the resulting evidence is published.
create or replace function pg_temp.career_source(sid text,title text,publisher text,url text,jurisdiction text,scope text,access_note text default '',effective_on text default null) returns jsonb
language sql as $$ select jsonb_build_object('source_id',sid,'title',title,'publisher',publisher,'url',url,'jurisdiction',jurisdiction,'scope',scope,'access_note',access_note,'effective_on',effective_on); $$;
create or replace function pg_temp.career_section(sources jsonb,kind text default 'source_informed',limited text default null) returns jsonb
language sql as $$ select jsonb_build_object('status',case when limited is null then 'source_checked' else 'limited' end,'kind',kind,'checked_on','2026-10-13','limitations',case when limited is null then '[]'::jsonb else jsonb_build_array(limited) end,'sources',sources); $$;

create temporary table career_review_candidates(n int,baseline text,payload jsonb) on commit preserve rows;
insert into career_review_candidates values
(1,'efb39e20a61381768e778a8732d8d909',$c${"description":"Evaluates patient information, discusses treatment and monitors care. Work varies by medical specialty.","responsibilities":["Assess clinical information","Explain care and treatment","Keep records and coordinate referrals"],"skills":["Clinical reasoning","Active listening","Communication"],"refs":[["29-1215.00","Family Medicine Physicians","SI","example","One medical specialty; not all doctors."],["29-1216.00","General Internal Medicine Physicians","ISR","example","Adult internal medicine example; not specialist eligibility."]],"routes":[["MMC education and recognition","Malaysian Medical Council","https://mmc.gov.my/medical-education-recognition-2/"],["MMC registration types","Malaysian Medical Council","https://mmc.gov.my/registrations/"]],"stages":[["Check medical programme admission","Check the institution and currently effective MMC entry guidance for your qualifications."],["Choose a recognised medical qualification","Confirm the exact qualification is recognised by MMC before committing to study."],["Check provisional registration and supervised training","Apply through the applicable provisional-registration and approved training process. Placement is not guaranteed."],["Check full registration and practising conditions","Confirm current MMC registration and practising-certificate conditions before practice."]]}$c$::jsonb),
(2,'94ce9a0ac44522b6361348fc6b943b6b',$c${"code":"ISC","description":"Reviews and supplies medicines, checks prescriptions and advises patients and healthcare colleagues about their use.","responsibilities":["Evaluate prescriptions","Advise on medicine use","Coordinate with healthcare colleagues"],"skills":["Critical thinking","Patient communication","Attention to detail"],"refs":[["29-1051.00","Pharmacists","ISC","direct","Occupational reference; Malaysian registration is separate."]],"routes":[["Recognised pharmacy qualifications","Pharmacy Board Malaysia / MOH","https://pharmacy.moh.gov.my/en/content/list-recognized-pharmacy-degree-pharmacy-board-malaysia.html"],["Qualifying examination","Pharmacy Board Malaysia / MOH","https://pharmacy.moh.gov.my/en/content/qualifying-examination-practice-pharmacy.html"],["PRP training guide","Pharmacy Board Malaysia / MOH","https://pharmacy.moh.gov.my/sites/default/files/document-upload/general-guide-health-clinics.pdf"]],"stages":[["Check pharmacy programme admission","Confirm the programme admission conditions and recognition of its exact qualification."],["Complete a recognised pharmacy qualification","Compare the programme with Pharmacy Board Malaysia recognition requirements."],["Check examination and provisional registration","Meet the qualifying-examination and provisional-registration conditions applicable to your circumstances."],["Complete approved PRP training","Follow the supervised PRP process at an approved training premise; satisfactory completion is required."],["Apply for full registration","Confirm the current full-registration conditions with Pharmacy Board Malaysia."]]}$c$::jsonb),
(3,'98d138d7dbb80117819884ed033f389f',$c${"description":"Works on biomedical laboratory investigations or research. Research and clinical laboratory practice are different routes.","responsibilities":["Prepare and examine samples","Use laboratory equipment safely","Analyse and communicate findings"],"skills":["Scientific reasoning","Laboratory methods","Evidence communication"],"refs":[["19-1042.00","Medical Scientists, Except Epidemiologists","IR","example","Biomedical research example; not clinical registration."],["29-2011.00","Medical and Clinical Laboratory Technologists","IRC","example","Clinical laboratory example; not a Malaysian registration equivalence."]],"routes":[["UM Biomedical Science programme","Universiti Malaya","https://study.um.edu.my/Bachelor-of-Biomedical-Science"],["MAHPC information and recognised-qualification resources","Malaysian Allied Health Professions Council / MOH","https://hq.moh.gov.my/alliedhealth/index.php/ms/site-mahpc/info-mahpc"]],"limited":"A specific biomedical qualification-to-clinical-registration mapping has not been verified; linked recognised-qualification documents were inaccessible.","stages":[["Choose research or clinical laboratory work","Identify the actual role; a broad biomedical title does not establish clinical eligibility."],["Compare programme content and admission","Review the chosen institution programme and check whether your qualification is accepted."],["Check the clinical qualification and registration route","For clinical work, confirm the actual profession and current MAHPC eligibility directly. No degree-to-registration equivalence is asserted here."],["Explore relevant laboratory or research roles","Use real role descriptions to compare the preparation expected for your intended work."]]}$c$::jsonb),
(4,'062a938a3b355309f433e882b9a1d026',$c${"code":"RIC","description":"Plans and evaluates civil infrastructure, analyses design information and monitors construction against technical and safety requirements.","responsibilities":["Develop infrastructure designs","Assess loads and materials","Monitor project specifications and safety"],"skills":["Engineering analysis","Technical design","Project communication"],"refs":[["17-2051.00","Civil Engineers","RIC","direct","Engineering work reference; BEM categories determine professional status."]],"routes":[["Engineering accreditation","Board of Engineers Malaysia","https://bem.org.my/Landing/acc"],["Engineering registration categories","Board of Engineers Malaysia","https://bem.org.my/landing/register"]],"stages":[["Check engineering admission and accreditation","Verify programme admission and the exact engineering degree accreditation."],["Complete a recognised engineering qualification","Do not assume a diploma or engineering-technology award is equivalent to the recognised engineering-degree route."],["Apply for Graduate Engineer registration","Check the BEM category and qualification requirements applicable to your award."],["Explore the Professional Engineer route","If pursuing professional status, meet its separate experience and assessment conditions. Practice permissions differ by category."]]}$c$::jsonb),
(5,'786d9c8164845c24e1693280f8b2f192',$c${"code":"IC","description":"Develops software from user and system requirements, tests reliability and improves existing applications.","responsibilities":["Evaluate user requirements","Design and develop software","Test and improve applications"],"skills":["Programming","Systems analysis","Problem solving"],"refs":[["15-1252.00","Software Developers","IC","related","Software Engineer is a reported title; not every software specialism."]],"study":"Explore computing or software study; check each programme admission and content."}$c$::jsonb),
(6,'3c11964156c894f04b5c8064c179f69f',$c${"code":"IC","description":"Develops analytical methods, prepares data, evaluates statistical or computational models and communicates findings.","responsibilities":["Prepare and explore data","Build and evaluate models","Present analytical findings"],"skills":["Mathematical reasoning","Programming","Critical evaluation"],"refs":[["15-2051.00","Data Scientists","IC","direct","U.S. occupational reference; not Malaysian hiring or degree requirements."]],"study":"Explore quantitative or computing study; compare statistics and programming content."}$c$::jsonb),
(7,'4b84b8bb67c743aa6e0499d9ae052ad2',$c${"code":"RCA","description":"Develops building designs and technical documentation, coordinates requirements and communicates with project teams.","responsibilities":["Develop building designs","Prepare technical drawings","Coordinate client and project requirements"],"skills":["Design reasoning","Technical communication","Coordination"],"refs":[["17-1011.00","Architects, Except Landscape and Naval","RCA","related","Building architecture reference; not landscape or naval architecture."]],"routes":[["Recognised architectural programmes","Lembaga Arkitek Malaysia","https://classic.lam.gov.my/list-of-recognised-architectural-programmes"],["Graduate Architect requirements","Lembaga Arkitek Malaysia","https://classic.lam.gov.my/index.php/requirements-registration-graduate-architects"],["Architect registration requirements","Lembaga Arkitek Malaysia","https://classic.lam.gov.my/index.php/registration-requirement-architects"]],"stages":[["Check admission and LAM recognition","Verify the programme and the recognised Part I and Part II route, or applicable examination route."],["Meet Part I and Part II requirements","An undergraduate award alone must not be assumed to confer registered Architect status."],["Apply for Graduate Architect registration","Check the separate Graduate Architect registration conditions."],["Meet practical experience and Part III requirements","Confirm the prescribed experience and professional examination requirements with LAM."],["Apply for Architect registration","Meet LAM registration conditions before presenting yourself as a registered Architect."]]}$c$::jsonb),
(8,'b077204aaeac715505d3721976cc72a0',$c${"code":"AC","description":"Creates visual materials from a brief, develops concepts, arranges text and images and prepares production files.","responsibilities":["Interpret visual communication briefs","Develop and review design concepts","Prepare production-ready artwork"],"skills":["Visual communication","Active listening","Time management"],"refs":[["27-1024.00","Graphic Designers","AC","direct","Occupational design reference, not a mandatory degree route."]],"study":"Explore graphic design or visual communication study; compare portfolios and programme content."}$c$::jsonb),
(9,'e8922c6f6238b9343342331bf410b174',$c${"description":"Creates moving-image or interactive media. Animation and digital-interface design are distinct specialisms.","responsibilities":["Develop media concepts","Create and refine visual assets","Coordinate creative production"],"skills":["Creative communication","Problem solving","Production planning"],"refs":[["27-1014.00","Special Effects Artists and Animators","AR","example","Animation and visual-effects branch, not every multimedia role."],["15-1255.00","Web and Digital Interface Designers","IAC","example","Interface-design branch, not an animation profile."]],"study":"Choose an animation, digital media or interface-design focus before comparing study content."}$c$::jsonb),
(10,'9117913be8663571fb68f6e8635bb66a',$c${"code":"SCI","description":"Monitors patients, records care information, delivers planned nursing care and communicates with patients and healthcare colleagues.","responsibilities":["Monitor patient conditions","Record nursing care information","Coordinate planned patient care"],"skills":["Active listening","Care coordination","Clinical observation"],"refs":[["29-1141.00","Registered Nurses","SCI","related","Registered-nurse work reference; Malaysian registration is separate."]],"routes":[["Nursing accreditation standards 2025","Nursing Board Malaysia / MOH","https://hq.moh.gov.my/nursing/wp-content/uploads/2025/06/Buku-Standard-Criteria-For-Accreditation-of-Nursing-Programes-2025.pdf"],["Nursing registration and practice FAQ","Nursing Board Malaysia / MOH","https://hq.moh.gov.my/nursing/en/faq/"]],"stages":[["Check approved nursing programme admission","Compare the actual nursing diploma or degree entry criteria. STAM routes are conditional, not universally accepted or excluded."],["Complete nursing and clinical education","A general healthcare award is not automatically an approved nursing qualification."],["Meet examination and registration conditions","Check Nursing Board examination and registration requirements for your route."],["Check practising-certificate requirements","Confirm the certificate and current conditions required for practice."]]}$c$::jsonb),
(11,'9bed46bac3c99fb5fee51a7836f98a6a',$c${"code":"CEI","description":"Prepares and examines financial records, resolves discrepancies and supports financial reporting. Tax and audit duties vary by role.","responsibilities":["Prepare and review financial records","Investigate discrepancies","Analyse financial information"],"skills":["Mathematical reasoning","Critical evaluation","Written communication"],"refs":[["13-2011.00","Accountants and Auditors","CEI","related","Broad accounting/audit reference; not authority for every professional service."]],"routes":[["MIA membership application checklist","Malaysian Institute of Accountants","https://mia.org.my/storage/2025/11/CA-Application-Checklist_24Oct2025_Final.pdf"]],"limited":"MIA indexed official guidance was available, but direct document retrieval was blocked. Detailed membership and public-practice eligibility must be checked directly; no finance or business degree equivalence is asserted.","stages":[["Distinguish employment and professional membership","Identify your intended role and whether professional membership or practice permissions are relevant."],["Check your qualification route with MIA","Confirm the actual eligible qualification or professional-membership route directly with MIA."],["Check current experience and membership conditions","Do not rely on a degree title alone. Detailed eligibility is not certified by this page."],["Plan an application after checking eligibility","Treat this as a planning suggestion, not approval of professional status."]]}$c$::jsonb),
(12,'0f8e46d981096d7046146b4b16d80520',$c${"code":"S","description":"Plans subject lessons, adapts teaching, assesses progress and works with students, families and colleagues.","responsibilities":["Plan and deliver subject lessons","Adapt activities to learning needs","Assess and discuss student progress"],"skills":["Teaching","Active listening","Learning strategies"],"refs":[["25-2031.00","Secondary School Teachers, Except Special and Career/Technical Education","S","related","General secondary teaching example; excludes special and career/technical teaching."]],"routes":[["DG9 education-service qualifications","Suruhanjaya Perkhidmatan Awam Malaysia","https://www.spa.gov.my/syarat-permohonan/ijazah-sarjana-muda-sarjana-doktor-falsafah/pegawai-perkhidmatan-pendidikan-gred-dg9"]],"stages":[["Identify teaching subject and school sector","Government and other school sectors may use different selection processes."],["Check admission to a suitable education route","Compare a recognised education degree or relevant subject degree plus a recognised teaching qualification."],["Complete the applicable teaching preparation","Verify the qualification requirements for the appointment you intend to seek."],["Follow the applicable appointment process","Qualifications do not guarantee a government post or secondary-school placement."]]}$c$::jsonb),
(13,'456aa7d9221212d3f7f1003d6883c025',$c${"code":"CI","description":"Evaluates information-security risks, checks safeguards, investigates incidents and communicates security procedures.","responsibilities":["Assess information-security risks","Monitor and investigate incidents","Evaluate and explain safeguards"],"skills":["Systems analysis","Problem solving","Risk communication"],"refs":[["15-1212.00","Information Security Analysts","CI","related","Information-security example; cybersecurity specialisms can differ."]],"study":"Explore computing or information-security study; check programme content and actual admission routes."}$c$::jsonb),
(14,'3df7c89b94ed946f975d33fe29924084',$c${"description":"In business-intelligence work, queries organisational data, maintains reporting tools and communicates trends and findings.","responsibilities":["Query and check business information","Maintain dashboards and reports","Explain trends to decision makers"],"skills":["Critical evaluation","Data communication","Problem solving"],"refs":[["15-2051.01","Business Intelligence Analysts","CIE","example","Business-intelligence example, not a universal profile for all data analysts."]],"study":"Explore quantitative, business-analysis or computing study; compare the skills taught for your intended role."}$c$::jsonb);

do $$
declare candidate record; c public.careers; cid uuid; previous public.career_content_migration_outcomes;
 sources jsonb; route_sources jsonb; occupations jsonb; sections jsonb; reviewed jsonb; stage_review jsonb;
 e jsonb; s jsonb; level text; seq int; data jsonb; limited text; current_hash text;
 mk constant text='0018-reviewed-career-content';
begin
 for candidate in select * from career_review_candidates order by n loop
  cid=('b0000000-0000-4000-8000-'||lpad(candidate.n::text,12,'0'))::uuid;
  select * into c from public.careers where id=cid for update;
  if not found then
   insert into public.career_content_migration_outcomes values(mk,cid,'missing','Original seeded career is absent; no replacement inserted.',null,now()) on conflict do nothing; continue;
  end if;
  select * into previous from public.career_content_migration_outcomes where migration_key=mk and career_id=cid;
  current_hash=md5(public.career_reviewed_snapshot(c)::text);
  if previous.reviewed_hash is not null and previous.reviewed_hash=current_hash then continue; end if;
  insert into public.career_content_migration_backups(migration_key,career_id,career_record,stage_records)
   select mk,cid,to_jsonb(c),coalesce((select jsonb_agg(to_jsonb(p) order by p.from_education_level,p.stage_order) from public.career_pathway_stages p where career_id=cid),'[]') on conflict do nothing;
  if previous.career_id is not null or md5(public.career_content_snapshot(c)::text)<>candidate.baseline or
    c.reference_occupations<>'[]'::jsonb or c.content_review<>'{"status":"pending","checked_on":null,"limitations":[],"sections":{}}'::jsonb or
    exists(select 1 from public.career_pathway_stages where career_id=cid and content_review<>'{"status":"pending","kind":"nexus_planning","checked_on":null,"limitations":[],"sources":[]}'::jsonb) then
   update public.careers set content_review=public.pending_career_review(content_review) where id=cid;
   update public.career_pathway_stages set content_review=content_review||jsonb_build_object('status','pending','checked_on',null) where career_id=cid;
   insert into public.career_content_migration_outcomes values(mk,cid,'skipped','Content or a stage differs from the original seed; preserve and manually review.',null,now())
    on conflict(migration_key,career_id) do update set status='skipped',reason=excluded.reason,recorded_at=now(); continue;
  end if;
  data=candidate.payload; limited=data->>'limited'; sources='[]'; occupations='[]'; route_sources='[]';
  for e in select * from jsonb_array_elements(data->'refs') loop
   sources=sources||jsonb_build_array(pg_temp.career_source(e->>0,e->>1,'O*NET OnLine','https://www.onetonline.org/link/summary/'||(e->>0),'United States','Occupational description, tasks and interests; not Malaysian admission or licensing.'));
   occupations=occupations||jsonb_build_array(jsonb_build_object('reference_id',e->>0,'name',e->>1,'interest_code',e->>2,'mapping_kind',e->>3,'scope_note',e->>4,'interest_source_id',e->>0));
  end loop;
  for e in select * from jsonb_array_elements(coalesce(data->'routes','[]')) loop
   route_sources=route_sources||jsonb_build_array(pg_temp.career_source(e->>2,e->>0,e->>1,e->>2,'Malaysia','Check the applicable qualification, admission or professional route; no personal eligibility decision.',coalesce(limited,'')));
  end loop;
  if candidate.n=1 then route_sources=route_sources||jsonb_build_array(pg_temp.career_source('mmc-upcoming','MMC upcoming medical entry guidance','Malaysian Medical Council','https://mmc.gov.my/medical-education-recognition-2/','Malaysia','Upcoming minimum-entry document; not effective before 1 January 2027.','','2027-01-01')); end if;
  if route_sources='[]' then route_sources=jsonb_build_array(pg_temp.career_source('mqr','Malaysian Qualifications Register','Malaysian Qualifications Agency','https://www.mqa.gov.my/mqr/english/ecarianakr.cfm','Malaysia','Programme accreditation lookup; not admission eligibility.')); end if;
  sections=jsonb_build_object('overview',pg_temp.career_section(sources),'responsibilities',pg_temp.career_section(sources),'skills',pg_temp.career_section(sources),
   'subjects',pg_temp.career_section(sources,'nexus_planning'),'interests',pg_temp.career_section(sources),
   'study_options',pg_temp.career_section(route_sources,case when data?'study' or limited is not null then 'nexus_planning' else 'source_informed' end,limited));
  reviewed=jsonb_build_object('status',case when limited is null then 'source_checked' else 'limited' end,'checked_on','2026-10-13','limitations',case when limited is null then '[]'::jsonb else jsonb_build_array(limited) end,'sections',sections);
  update public.careers set description=data->>'description',responsibilities=array(select jsonb_array_elements_text(data->'responsibilities')),
   required_skills=array(select jsonb_array_elements_text(data->'skills')),riasec_profile=data->>'code',reference_occupations=occupations,
   education_routes=case when data?'study' then array[data->>'study'] else array(select x->>1 from jsonb_array_elements(data->'stages') x) end,
   content_review=public.pending_career_review(reviewed) where id=cid;
  update public.careers set content_review=reviewed where id=cid;
  -- Old generic rows are recoverable from the restricted backup; career IDs and mappings stay intact.
  delete from public.career_pathway_stages where career_id=cid;
  if not data?'stages' then data=data||jsonb_build_object('stages',jsonb_build_array(
   jsonb_build_array('Choose a study direction',data->>'study'),
   jsonb_build_array('Check actual programme entry and accreditation','Compare official admission and MQR records. No automatic STAM admission, diploma progression or credit transfer is promised.'),
   jsonb_build_array('Practise relevant skills','Use projects or a portfolio to explore the work. This is preparation advice, not a universal hiring requirement.'),
   jsonb_build_array('Explore real role descriptions','Compare employer expectations for your chosen specialism; no employment outcome is guaranteed.'))); end if;
  stage_review=pg_temp.career_section(route_sources,case when candidate.n in (5,6,8,9,13,14) or limited is not null then 'nexus_planning' else 'source_informed' end,limited);
  foreach level in array array['spm','stpm','stam','matriculation','foundation','diploma'] loop
   seq=0;
   for s in select * from jsonb_array_elements(data->'stages') loop
    seq=seq+1;
    insert into public.career_pathway_stages(career_id,from_education_level,stage_order,stage_title,stage_description,focus_points,content_review)
     values(cid,level,seq,s->>0,case when seq=1 then 'Starting from '||upper(level)||': check your actual qualification against the selected route. ' else '' end||(s->>1),
      case when seq=1 then array['Confirm programme-specific admission','Compare suitable options'] when candidate.n in (5,6,8,9,13,14) and seq=3 then array(select jsonb_array_elements_text(data->'skills')) else '{}'::text[] end,stage_review);
   end loop;
  end loop;
  select * into c from public.careers where id=cid;
  insert into public.career_content_migration_outcomes values(mk,cid,'updated','Original seed replaced with scoped source-backed content; limitations retained.',md5(public.career_reviewed_snapshot(c)::text),now()) on conflict do nothing;
 end loop;
end;
$$;
drop table career_review_candidates;
